def _col_name_to_index(name):
    """列名（A, B, ..., Z, AA, ...）转 1-based 列索引。"""
    name = name.upper().strip()
    if not re.match(r"^[A-Z]+$", name):
        return None
    n = 0
    for c in name:
        n = n * 26 + (ord(c) - ord("A") + 1)
    return n

