    else:
        try:
            i = header.index(spec) + 1
            col_indices.append(i)
        except ValueError:
            print(f"表头中未找到列名: {spec}", file=sys.stderr)
            sys.exit(1)

keys = [k.strip() for k in args.on.split(",") if k.strip()]
for k in keys:
    if k not in left.columns:
        print(f"左表缺少键列: {k}", file=sys.stderr)
        sys.exit(1)
    if k not in right.columns:
        print(f"右表缺少键列: {k}", file=sys.stderr)
        sys.exit(1)

if args.rename:
    for item in args.rename:
        if ":" not in item:
            print(f"无效项（需 原名:新名 或 索引:新名）: {item}", file=sys.stderr)
            sys.exit(1)
        left, new_name = item.split(":", 1)
        left, new_name = left.strip(), new_name.strip()
        if not new_name:
            continue
        if left.isdigit():
            idx = int(left)
            if idx < 0 or idx >= len(names):
                print(f"索引越界: {idx}", file=sys.stderr)
                sys.exit(1)
            old_name = names[idx]
        else:
            old_name = left
            if old_name not in names:
                print(f"工作表不存在: {old_name}", file=sys.stderr)
                sys.exit(1)
        if len(new_name) > 31:
            new_name = new_name[:31]
        if new_name != old_name and new_name in names:
            print(f"新名已存在: {new_name}", file=sys.stderr)
            sys.exit(1)

for spec in args.lookups:
    if ":" not in spec:
        print(f"无效 lookups 项（需 文件:键列）: {spec}", file=sys.stderr)
        sys.exit(1)

if on_col not in df.columns:
    print(f"主表缺少键列: {on_col}", file=sys.stderr)
    sys.exit(1)
if on_col not in right.columns:
    print(f"查找表 {fpath} 缺少键列: {on_col}", file=sys.stderr)
    sys.exit(1)
